struct kioctx *ioctx_alloc(unsigned nr_events) {
    struct kioctx *ioctx;
    int err;

    if (nr_events >= (UINT_MAX / sizeof(struct aio_ring_info)))
        nr_events = UINT_MAX / sizeof(struct aio_ring_info);
    nr_events = min_t(unsigned, nr_events, nr_aio_events_max);

    ioctx = kzalloc(sizeof(*ioctx), GFP_KERNEL);
    if (!ioctx)
        return ERR_PTR(-ENOMEM);

    init_waitqueue_head(&ioctx->wait);
    spin_lock_init(&ioctx->ctx_lock);

    atomic_long_set(&ioctx->reqs, 0);
    atomic_long_set(&ioctx->events, 0);

    err = aio_setup_ring(ioctx, nr_events);
    if (err) {
        kfree(ioctx);
        return ERR_PTR(err);
    }

    if (unlikely(atomic_inc_return(&nr_kioctx) > max_kioctx)) {
        aio_teardown_ring(ioctx);
        kfree(ioctx);
        return ERR_PTR(-EAGAIN);
    }

    return ioctx;
}

#include <linux/slab.h>
#include <linux/spinlock.h>
#include <linux/wait.h>
#include <linux/rwsem.h>
#include <linux/uio.h>
#include <linux/errno.h>

struct kioctx {
    unsigned        nr_events;
    spinlock_t      lock;
    wait_queue_head_t wait;
    struct rw_semaphore ctx_lock;
    struct kioctx   *next;
};

struct kioctx *ioctx_init(unsigned nr_events)
{
    struct kioctx *ctx;
    unsigned real_nr_events;

    if (nr_events == 0)
        return ERR_PTR(-EINVAL);

    real_nr_events = nr_events;

    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    ctx->nr_events = real_nr_events;

    spin_lock_init(&ctx->lock);
    init_waitqueue_head(&ctx->wait);
    init_rwsem(&ctx->ctx_lock);

    return ctx;
}

struct kioctx *ioctx_alloc(unsigned nr_events)
{
    struct kioctx *ctx;
    int err = 0;

    if (unlikely(nr_events >= (UINT_MAX / sizeof(struct io_event))))
        return ERR_PTR(-EINVAL);

    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    spin_lock_init(&ctx->ctx_lock);
    init_waitqueue_head(&ctx->wait);
    atomic_set(&ctx->users, 1);
    ctx->nr_events = nr_events;

    if (aio_max_instances) {
        if (!atomic_sub_and_test(1, &aio_nr);
            atomic_inc(&aio_nr) && atomic_dec(&aio_nr);
            atomic_inc(&aio_nr);
        } else {
            atomic_inc(&aio_nr);
        }
    }

    if (unlikely(err)) {
        kfree(ctx);
        return ERR_PTR(err);
    }

    return ctx;
}

#include <linux/kernel.h>
#include <linux/slab.h>
#include <linux/spinlock.h>
#include <linux/wait.h>

struct kioctx {
    unsigned nr_events;
    spinlock_t lock;
    wait_queue_head_t wait;
};

struct kioctx *ioctx_alloc(unsigned nr_events) {
    struct kioctx *ctx;

    if (nr_events == 0)
        nr_events = 1;

    ctx = kmalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return ERR_PTR(-ENOMEM);

    spin_lock_init(&ctx->lock);
    init_waitqueue_head(&ctx->wait);

    ctx->nr_events = nr_events;

    return ctx;
}
